begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email) select ('ab180000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','variants-'||n||'@example.invalid' from generate_series(1,3) n;
insert into public.staff_users(user_id,role) values('ab180000-0000-4000-8000-000000000001','office'),('ab180000-0000-4000-8000-000000000002','technician');
insert into public.customers(id,name) values('cc180000-0000-4000-8000-000000000001','Klient wariantów');
create function pg_temp.variant(n integer,quantity integer default 8000,sale integer default 200) returns jsonb language sql as $$select jsonb_build_object('id','dd180000-0000-4000-8000-'||lpad(n::text,12,'0'),'name','Wariant '||n,'internalNote','PRIVATE NOTE','customerNote','','targetMarginBasisPoints',3000,'overrideNetCents',null,'lines',jsonb_build_array(jsonb_build_object('id','df180000-0000-4000-8000-'||lpad(n::text,12,'0'),'catalogId',null,'code','TEST','name','Materiał','description','','category','material','unit','meter','quantityMills',quantity,'costCents',100,'saleCents',sale,'vatBasisPoints',2300,'discountBasisPoints',0)))$$;
create function pg_temp.offer(variants jsonb default jsonb_build_array(pg_temp.variant(1),pg_temp.variant(2,16000,350))) returns jsonb language sql as $$select jsonb_build_object('customerId','cc180000-0000-4000-8000-000000000001','locationId',null,'title','Porównanie wariantów','workType','split','technical',jsonb_build_object('lengthMills',8000,'laborMills',0,'travelMills',0),'mainVariantId','dd180000-0000-4000-8000-000000000002','archived',false,'variants',variants)$$;
create function pg_temp.save(data jsonb default pg_temp.offer(),id uuid default 'ee180000-0000-4000-8000-000000000001') returns jsonb language sql as $$select public.save_offer(id,data,null)$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','ab180000-0000-4000-8000-000000000001',true);
select is(jsonb_array_length(pg_temp.save()->'variants'),2,'Two alternatives saved together');
select is(pg_temp.save()->>'mainVariantId','dd180000-0000-4000-8000-000000000002','Main variant choice retained');
select is(pg_temp.save()->'computed'->'dd180000-0000-4000-8000-000000000001'->>'netCents','1600','First net computed by database');
select is(pg_temp.save()->'computed'->'dd180000-0000-4000-8000-000000000002'->>'netCents','5600','Second net computed independently');
select is(pg_temp.save()->'computed'->'dd180000-0000-4000-8000-000000000002'->>'costCents','1600','Second cost computed independently');
select is(pg_temp.save()->'computed'->'dd180000-0000-4000-8000-000000000002'->>'grossCents','6888','VAT included in comparison');
select is(pg_temp.save()->>'version','0','Same creation request is idempotent');
reset role;
select is((select count(*)::int from public.audit_logs where table_name='offers' and row_id='ee180000-0000-4000-8000-000000000001'),1,'Only one audit after retry');
set local role authenticated;
select throws_ok($$select pg_temp.save(pg_temp.offer(jsonb_build_array(pg_temp.variant(1),pg_temp.variant(1))))$$,'22023',null,'Duplicate variant identities rejected');
select throws_ok($$select pg_temp.save(pg_temp.offer(jsonb_build_array(pg_temp.variant(1))))$$,'22023',null,'Missing main variant rejected');
select throws_ok($$select pg_temp.save(pg_temp.offer(jsonb_build_array(pg_temp.variant(1),pg_temp.variant(2,0))), 'ee180000-0000-4000-8000-000000000002')$$,'22023',null,'Invalid second alternative aborts request');
reset role;
select is((select count(*)::int from public.offers where id='ee180000-0000-4000-8000-000000000002'),0,'No partial offer after invalid alternative');
set local role authenticated;
select is(jsonb_array_length(pg_temp.save(pg_temp.offer((select jsonb_agg(pg_temp.variant(n)) from generate_series(1,5) n)),'ee180000-0000-4000-8000-000000000003')->'variants'),5,'Five variants supported');
select throws_ok($$select pg_temp.save(pg_temp.offer((select jsonb_agg(pg_temp.variant(n)) from generate_series(1,6) n)),'ee180000-0000-4000-8000-000000000004')$$,'22023',null,'Six variants rejected');
select set_config('request.jwt.claim.sub','ab180000-0000-4000-8000-000000000002',true);
select throws_ok($$select pg_temp.save()$$,'42501',null,'Technician denied internal variant creation');
select set_config('request.jwt.claim.sub','ab180000-0000-4000-8000-000000000003',true);
select throws_ok($$select pg_temp.save()$$,'42501',null,'Account without internal role denied');
reset role;
set local role anon;
select throws_ok($$select public.save_offer('ee180000-0000-4000-8000-000000000001','{}',null)$$,'42501',null,'Anonymous creation denied');
select * from finish();
rollback;
